  "build.loyalty.badgeBoostSlots": "+12 boost slots on Platinum",
  "build.loyalty.badgeCashback": "Cashback rate grows 2% → 5%",
  "build.loyalty.badgeHireFee": "Hire-fee drops 12% → 4%",
  "build.loyalty.badgeSubDiscount": "Subscription discount up to −25%",
  "build.loyalty.cashbackAccrued": "AEV accrued",
  "build.loyalty.cashbackCurrentRate": "Current rate",
  "build.loyalty.cashbackOrders": "Orders",
  "build.loyalty.cashbackWithdrawPost": ", the Loyalty block at the bottom.",
  "build.loyalty.cashbackWithdrawPre": "To withdraw AEV to your wallet → go to",
  "build.loyalty.currentTierLabel": "Your current tier",
  "build.loyalty.faqA1": "Every ACCEPTED application on a vacancy in your project = 1 hire. Plus an APPROVED trial task. No double-count: the same application is counted once.",
  "build.loyalty.faqA2": "No. Tiers never expire — it's a lifetime counter. Once you reach Gold, you stay Gold (or higher) forever.",
  "build.loyalty.faqA3": "At the moment an order is created via POST /subscriptions/start. The discount is locked into the order — even if you later move to the next tier, the current subscription keeps its 'old' price until it's reissued.",
  "build.loyalty.faqA4": "In AEV — the native AEVION token. Stored in the built-in AEV wallet (the /aev module). It can be redeemed for AEVION features or converted once a DEX listing appears (roadmap Q4 2026).",
  "build.loyalty.faqA5": "For a large agency / contractor with 5–10 active projects — 6–12 months. At Platinum the hire-fee becomes 4% — already three times cheaper than an HH agency. The payoff is obvious after the very first mid-size deal.",
  "build.loyalty.faqQ1": "How are hires counted?",
  "build.loyalty.faqQ2": "Can I lose my tier?",
  "build.loyalty.faqQ3": "When does the subscription discount apply?",
  "build.loyalty.faqQ4": "Does cashback go to real crypto?",
  "build.loyalty.faqQ5": "The Platinum tier needs 50 hires — is that realistic?",
  "build.loyalty.heroBodyEnd": ". HH has none of this — no pricing tiers, no token payback.",
  "build.loyalty.heroBodyHighlight1": "hire-fee drops",
  "build.loyalty.heroBodyHighlight2": "AEV cashback grows",
  "build.loyalty.heroBodyHighlight3": "you get a subscription discount",
  "build.loyalty.heroBodyHighlight4": "extra boost slots unlock",
  "build.loyalty.heroBodyMid1": ", ",
  "build.loyalty.heroBodyMid2": ", ",
  "build.loyalty.heroBodyMid3": ", and ",
  "build.loyalty.heroBodyPre": "5 loyalty tiers — from Default to Platinum. Every step upgrades 4 things at once: ",
  "build.loyalty.heroHeadline": "The more you hire, the less you pay. And the more you get back.",
  "build.loyalty.hiresCount": "{hires} hires",
  "build.loyalty.insight1Body": "Recruiter pays — gets AEV — spends it on boost / subscription — we take a cut. No leakage to an external payment provider more than once a year; cashback stays closed-loop.",
  "build.loyalty.insight1Title": "Closed-loop economy",
  "build.loyalty.insight2Body": "The longer a recruiter stays with us, the more it pays to remain. Churn resistance is built into the product, not bolted on as a retention program.",
  "build.loyalty.insight2Title": "Network effect through tiers",
  "build.loyalty.insight3Body": "Every ACCEPTED hire enriches the match engine. In 12 months we'll have signal density in the construction vertical that HH doesn't have.",
  "build.loyalty.insight4Body": "Default: 12% hire-fee + 0% cashback cost. Platinum: 4% hire-fee + 5% cashback. Margin at the Platinum tier = 4% − 5% × usage_share — offset by subscription fees and boost add-ons.",
  "build.loyalty.insight4Title": "Margin",
  "build.loyalty.investorsCta": "Full pitch deck → /why-aevion",
  "build.loyalty.investorsTitle": "Tokenomics HH won't replicate",
