  "pricing.glossary.category.auth": "Authentication",
  "pricing.glossary.category.billing": "Billing & metrics",
  "pricing.glossary.category.compliance": "Compliance",
  "pricing.glossary.category.legal": "Legal & IP",
  "pricing.glossary.category.ops": "Operations",
  "pricing.glossary.category.tech": "Tech",
  "pricing.glossary.def.arr": "Annual Recurring Revenue — key SaaS metric. AEVION publishes aggregate ARR in annual reports.",
  "pricing.glossary.def.byok": "Customer brings their own encryption keys (e.g. AWS KMS, Azure Key Vault). Available on Enterprise tier.",
  "pricing.glossary.def.cac": "Cost to acquire one customer. LTV/CAC > 3 indicates a healthy SaaS.",
  "pricing.glossary.def.dpa": "Data processing agreement between customer and SaaS. Required by GDPR. Available on AEVION Enterprise.",
  "pricing.glossary.def.eidas": "EU Regulation 910/2014 on trust services: e-identification, signature, seal, delivery. AEVION QSign is eIDAS-compatible.",
  "pricing.glossary.def.fz152": "Russian Federal Law on Personal Data. AEVION compliant: Russian citizen data stays on RF servers for Russian customers.",
  "pricing.glossary.def.gdpr": "EU regulation on personal data protection (2018). AEVION offers data residency in EU/RU/KZ, full export and right-to-be-forgotten.",
  "pricing.glossary.def.hsm": "Hardware Security Module for cryptographic keys. AEVION uses HSM-compatible storage with 90-day key rotation.",
  "pricing.glossary.def.ip": "Intellectual Property: copyrights, trademarks, patents, know-how. AEVION QRight + IP Bureau cover the full IP lifecycle.",
  "pricing.glossary.def.iso27001": "International standard for information security management. AEVION is ISO 27001 certified for Enterprise tier.",
  "pricing.glossary.def.ltv": "Total revenue per customer over their lifetime. AEVION affiliates earn 20% of LTV.",
  "pricing.glossary.def.mfa": "Two-factor (or more) authentication. Mandatory for all AEVION accounts.",
  "pricing.glossary.def.mrr": "Monthly Recurring Revenue. ARR = MRR × 12.",
  "pricing.glossary.def.msa": "Master Services Agreement: umbrella terms for all SOW. AEVION uses MSA for Enterprise contracts.",
  "pricing.glossary.def.nda": "Non-Disclosure Agreement. AEVION QSign has an NDA template for one-click signing.",
  "pricing.glossary.def.nps": "Customer satisfaction metric (-100 to +100). AEVION NPS = +72 as of 2026-04.",
  "pricing.glossary.def.oidc": "JSON-based SSO over OAuth 2.0. AEVION OIDC + JWT for API auth.",
  "pricing.glossary.def.owasp": "Community for security best practices. OWASP Top-10 checks in AEVION CI.",
  "pricing.glossary.def.pcidss": "Payment card data security standard. AEVION QPayNet is Level 1 certified for embedded payments.",
  "pricing.glossary.def.qes": "Qualified Electronic Signature (eIDAS). Legally equivalent to handwritten in all EU member states.",
  "pricing.glossary.def.rbac": "Role-Based Access Control with granular per-object permissions. AEVION includes MFA + SSO + RBAC.",
  "pricing.glossary.def.rfc3161": "IETF standard for time-stamping. Defines TSP request/response structure and timestamp authority signature format.",
  "pricing.glossary.def.rpo": "Acceptable data loss on failure. AEVION RPO ≤ 1 hour: replication across 2+ availability zones.",
  "pricing.glossary.def.rto": "Acceptable recovery time after failure. AEVION RTO ≤ 4 hours: quarterly DR drills.",
  "pricing.glossary.def.saas": "Software as a Service. AEVION is a multi-product SaaS with 40 modules.",
  "pricing.glossary.def.saml": "XML standard for SSO. AEVION supports SAML 2.0 IdP-initiated and SP-initiated.",
  "pricing.glossary.def.siem": "Security event monitoring system (Splunk, Datadog, ELK). AEVION exports audit log to SIEM via webhook or S3.",
  "pricing.glossary.def.sla": "Service Level Agreement: uptime, response-time, credits on breach. Published ladder (GET /api/quotas): Build 99.0%, Scale 99.5%, Enterprise 99.9%. The free Developer tier carries no uptime SLA.",
  "pricing.glossary.def.soc2": "AICPA audit standard for SaaS: Security, Availability, Processing Integrity, Confidentiality, Privacy. AEVION is SOC 2 Type II certified.",
  "pricing.glossary.def.sso": "Single sign-on via corporate IdP. AEVION supports SAML 2.0 and OpenID Connect.",
  "pricing.glossary.def.tsp": "Time-Stamping Protocol (RFC 3161). Proves a document existed at a specific moment without revealing content. AEVION QSign uses TSP for every signature.",
  "pricing.glossary.full.fz152": "On Personal Data (Russian Federation)",
