  "qreal.badge": "AEVION · new module · prototype",
  "qreal.brief.brief.ph": "E.g.: a rainy evening in the city, a girl feeds a street cat under a kiosk awning, rain drumming on tin, a passing trolleybus…",
  "qreal.brief.cta": "Break into shots",
  "qreal.brief.cta.busy": "Building storyboard…",
  "qreal.brief.h": "1 · Brief",
  "qreal.brief.sub": "Describe the scene in words — who is in the frame, where, what happens, what it sounds like.",
  "qreal.brief.title.ph": "Title (optional)",
  "qreal.cast.continuity.check": "Check continuity across shots",
  "qreal.cast.continuity.consistent": "Character holds across the scene",
  "qreal.cast.continuity.drifting": "Drift detected — tighten the canon or add a reference frame",
  "qreal.cast.continuity.insufficient": "Too few criteria scored for a verdict",
  "qreal.cast.continuity.na": "No character appears in two shots, so there is nothing to compare — this scene cannot demonstrate continuity.",
  "qreal.cast.h": "2b · Scene cast",
  "qreal.cast.ref.add": "Reference frame URL — locks the face harder than any wording",
  "qreal.cast.refs": "{n} reference image(s)",
  "qreal.cast.save": "Save and rebuild prompts",
  "qreal.cast.shots": "shots: {n}",
  "qreal.cast.sub": "A storyboard is written shot by shot, so the LLM re-describes the same hero every time — that is where drifting faces come from. Each character here has ONE canonical description that goes into every shot they appear in. Edit it and the render prompts are rebuilt.",
  "qreal.compare.h": "Live test — two engines, one QReal prompt",
  "qreal.compare.note": "Both clips are fully AI-generated: the boy, the dog, the yurt and every sound. Nobody was filmed. This is exactly what the module declares in its provenance manifest.",
  "qreal.compare.same.prompt": "same prompt, native audio",
  "qreal.compare.sub": "The hardest demo shot (a child and a dog) rendered from the exact same QReal render-prompt with realism directives. Judge for yourself which one is more alive.",
  "qreal.engines.h": "4 · Render engines",
  "qreal.engines.off": "not connected",
  "qreal.engines.on": "connected",
  "qreal.estimate.cached": "already cached, free",
  "qreal.estimate.prefix": "This film will cost about",
  "qreal.film.assemble": "Assemble film",
  "qreal.film.download": "Download film",
  "qreal.film.watch": "Watch the demo film (20s, free)",
  "qreal.hero.ethics": "Module principle: realism is the product, deception is not. Every frame carries a non-removable AI mark (C2PA-style manifest, sha256, EU AI Act art. 50).",
  "qreal.hero.lead": "Fully alive video without a single shoot. People, children, animals, birds, wind, rain and voices — generated and indistinguishable from reality. No actor, no reference footage: a brief in — a finished scene out.",
  "qreal.note.backend.down": "Backend is not responding — try again later.",
  "qreal.note.storyboard.llm": "Storyboard assembled by the AI director.",
  "qreal.note.storyboard.stub": "Storyboard assembled by the deterministic planner (no AI provider configured).",
  "qreal.preset.1": "Rainy evening in the old city: a girl feeds a street cat under a kiosk awning, rain drums on the tin roof, a trolleybus hisses past through puddles of neon reflections",
  "qreal.preset.1.label": "Rainy city",
  "qreal.preset.2": "Winter forest after fresh snowfall: a moose steps out onto a clearing, breath steaming in the frost, snow creaking underfoot, distant woodpecker taps",
  "qreal.preset.2.label": "Winter forest",
  "qreal.preset.3": "Night market in an old town at sunset: steam rises from cauldrons, a vendor pours tea in a high arc, a cat naps on the counter between spice sacks",
  "qreal.preset.3.label": "Sunset market",
  "qreal.preset.4": "Dawn over the steppe: feather grass waves in the wind, a boy runs out of a yurt with an Alabai dog, a golden eagle takes off from a wooden perch",
  "qreal.preset.4.label": "Steppe dawn",
  "qreal.preset.5": "An old fisherman mends a torn net on a wooden pier, seagulls land nearby begging for fish, the sunset gilds the bay",
  "qreal.preset.5.label": "Fisherman",
  "qreal.preset.6": "A girl launches a red kite on a windy green hill, her dog leaps beside her, clouds race across the sky",
  "qreal.preset.6.label": "Kite on a hill",
  "qreal.prov.h": "5 · Provenance",
  "qreal.prov.register": "Register authorship (QRight)",
  "qreal.prov.registered": "Registered in the IP registry —",
  "qreal.qc.h": "3 · Realism QC loop",
  "qreal.qc.judge": "Score this shot",
  "qreal.qc.judge.hide": "Hide scoring",
  "qreal.qc.na": "n/a",
  "qreal.qc.sub": "Every render is scored by a judge across 14 weighted realism criteria, each with anchored 1-5 levels. A shot below the threshold comes back with a verdict and its weakest criteria named. Regeneration is opt-in and capped — every retry costs real money. That scoring loop is the gap between QReal and reroll-culture generators.",
  "qreal.qc.submit": "Submit scores",
  "qreal.qc.threshold": "Acceptance threshold: {v} on a 0-1 scale (about \"4 out of 5\"). Below it the judge returns a regeneration verdict — it does not spend on a retry by itself.",
